CREATE TABLE pgview_output_1.t(id int); INSERT INTO pgview_output_1.t VALUES(7);
CREATE VIEW pgview_output_1.constant_view AS SELECT 1 AS id;
CREATE VIEW pgview_output_1.two_cols AS SELECT 1 AS id, true AS enabled;
CREATE VIEW pgview_output_1.collated AS SELECT 'value' COLLATE pg_catalog."C" AS v;
CREATE SEQUENCE pgview_output_1.guard START 7;
CREATE TABLE pgview_output_1.receipt AS SELECT c.oid,c.relname,c.relkind,c.relfilenode,a.attnum,a.attname,a.atttypid,a.atttypmod,a.attcollation FROM pg_catalog.pg_class c LEFT JOIN pg_catalog.pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped WHERE c.relnamespace='pgview_output_1'::regnamespace AND c.relname<>'receipt'

